### 模块3：AES分级加密存储（crypto-store.js）

**分级策略**：

| 级别 | 数据类型 | 加密方式 | 密钥来源 |
|------|----------|----------|----------|
| L1-普通 | 体态统计计数 | 无加密 | - |
| L2-敏感 | 体态异常记录 | AES-ECB | 设备派生密钥 |
| L3-隐私 | 心率/压力原始数据 | AES-CBC + IV | 设备派生密钥 |

```javascript
// 核心逻辑
class CryptoStore {
  constructor() {
    this.keys = {
      L2: crypto.btoa('posture_guard_l2_key'), // 演示用固定密钥
      L3: crypto.btoa('posture_guard_l3_key'), // 实际应从设备密钥派生
    }
  }

  save(level, key, data) {
    const plain = JSON.stringify(data)
    if (level === 'L1') {
      return storage.set({ key, value: plain })
    }
    // L2/L3 使用 AES 加密
    const encKey = this.keys[level]
    crypto.encrypt({
      data: plain,
      key: encKey,
      algo: 'AES',
      success: (res) => storage.set({ key, value: res.data }),
      fail: (data, code) => console.error('Encrypt fail:', code)
    })
  }

  load(level, key, callback) {
    storage.get({
      key,
      success: (encrypted) => {
        if (level === 'L1') return callback(JSON.parse(encrypted))
        crypto.decrypt({
          data: encrypted,
          key: this.keys[level],
          algo: 'AES',
          success: (res) => callback(JSON.parse(res.data)),
          fail: () => callback(null)
        })
      }
    })
  }
}
```

