/**
 * posture-detector.js - 端侧AI体态识别算法
 *
 * 基于加速度计三轴数据的轻量化时序分析：
 * - 久坐检测：加速度方差极低 + 持续时间
 * - 低头前倾检测：z轴重力分量异常
 * - 跷二郎腿检测：x轴偏移 + y轴周期性微振
 *
 * 算法特点：
 * - 纯规则引擎，无需神经网络推理
 * - 滑动窗口统计（2秒窗口，~100样本）
 * - 低功耗：仅在采样时计算
 */

// 体态类型常量
const POSTURE_TYPE = {
  NORMAL: 'normal',
  SEDENTARY: 'sedentary',       // 久坐
  HEAD_TILT: 'head_tilt',       // 低头前倾
  LEG_CROSS: 'leg_cross',       // 跷二郎腿
}

// 体态类型中文名
const POSTURE_NAME = {
  [POSTURE_TYPE.NORMAL]: '正常',
  [POSTURE_TYPE.SEDENTARY]: '久坐',
  [POSTURE_TYPE.HEAD_TILT]: '低头前倾',
  [POSTURE_TYPE.LEG_CROSS]: '跷二郎腿',
}

class PostureDetector {
  constructor(options = {}) {
    // 滑动窗口大小（样本数）
    this.windowSize = options.windowSize || 100
    // 久坐提醒阈值（毫秒），默认30分钟
    this.sedentaryThreshold = options.sedentaryThreshold || 30 * 60 * 1000
    // 数据缓冲区
    this.buffer = []
    // 久坐起始时间
    this.sitStartTime = null
    // 今日久坐总时长（毫秒）
    this.todaySedentaryMs = 0
    // 上次检测时间
    this.lastDetectTime = 0
    // 检测结果回调
    this.onDetect = null
    // 状态变更回调
    this.onStateChange = null
  }

  /**
   * 输入加速度计样本数据
   * @param {Object} sample - { x: number, y: number, z: number }
   * @returns {Object} 检测结果 { type, confidence, detail }
   */
  input(sample) {
    const now = Date.now()
    // 控制检测频率，最多每200ms检测一次
    if (now - this.lastDetectTime < 200) {
      return null
    }
    this.lastDetectTime = now

    // 添加到滑动窗口
    this.buffer.push({
      x: sample.x,
      y: sample.y,
      z: sample.z,
      t: now,
    })
    if (this.buffer.length > this.windowSize) {
      this.buffer.shift()
    }

    // 窗口未满时返回正常
    if (this.buffer.length < 20) {
      return { type: POSTURE_TYPE.NORMAL, confidence: 1.0, detail: '数据采集中' }
    }

    // 执行检测
    const result = this._detect()

    // 触发回调
    if (this.onDetect) {
      this.onDetect(result)
    }

    return result
  }

  /**
   * 核心检测逻辑
   * @private
   */
  _detect() {
    const buffer = this.buffer

    // 1. 久坐检测：加速度方差极低 + 持续时间
    const sedentaryResult = this._detectSedentary(buffer)
    if (sedentaryResult.type === POSTURE_TYPE.SEDENTARY) {
      return sedentaryResult
    }

    // 2. 低头前倾检测：z轴重力分量异常
    const headTiltResult = this._detectHeadTilt(buffer)
    if (headTiltResult.type === POSTURE_TYPE.HEAD_TILT) {
      return headTiltResult
    }

    // 3. 跷二郎腿检测：x轴偏移 + y轴周期性微振
    const legCrossResult = this._detectLegCross(buffer)
    if (legCrossResult.type === POSTURE_TYPE.LEG_CROSS) {
      return legCrossResult
    }

    // 正常体态
    this.sitStartTime = null
    return { type: POSTURE_TYPE.NORMAL, confidence: 1.0, detail: '体态正常' }
  }

  /**
   * 久坐检测
   * 原理：加速度三轴方差极低表示几乎静止，持续超过阈值判定为久坐
   * @private
   */
  _detectSedentary(buffer) {
    const variance = this._calcVariance(buffer)
    const now = Date.now()

    // 方差阈值：低于0.01表示几乎静止
    const VARIANCE_THRESHOLD = 0.01

    if (variance < VARIANCE_THRESHOLD) {
      // 检测到静止状态
      if (!this.sitStartTime) {
        this.sitStartTime = now
      }

      const sedentaryDuration = now - this.sitStartTime
      if (sedentaryDuration > this.sedentaryThreshold) {
        return {
          type: POSTURE_TYPE.SEDENTARY,
          confidence: Math.min(0.95, 0.7 + sedentaryDuration / (this.sedentaryThreshold * 5)),
          detail: `已静坐 ${Math.floor(sedentaryDuration / 60000)} 分钟`,
        }
      }
    } else {
      // 活动状态，重置计时
      if (this.sitStartTime) {
        this.todaySedentaryMs += now - this.sitStartTime
      }
      this.sitStartTime = null
    }

    return { type: POSTURE_TYPE.NORMAL, confidence: 1.0, detail: '' }
  }

  /**
   * 低头前倾检测
   * 原理：正常站立时z轴约-1g，低头时z轴绝对值减小
   * @private
   */
  _detectHeadTilt(buffer) {
    const avgZ = this._calcAxisMean(buffer, 'z')
    const variance = this._calcVariance(buffer)

    // 静止或微动时才检测（运动中z轴变化大，不可靠）
    if (variance > 0.05) {
      return { type: POSTURE_TYPE.NORMAL, confidence: 1.0, detail: '' }
    }

    // 正常站立z≈-1.0, 低头时z在-0.6到-0.9之间
    const HEAD_TILT_Z_MIN = -0.95
    const HEAD_TILT_Z_MAX = -0.5

    if (avgZ > HEAD_TILT_Z_MIN && avgZ < HEAD_TILT_Z_MAX) {
      // z越接近-0.5，低头越严重
      const severity = (avgZ - HEAD_TILT_Z_MIN) / (HEAD_TILT_Z_MAX - HEAD_TILT_Z_MIN)
      return {
        type: POSTURE_TYPE.HEAD_TILT,
        confidence: Math.min(0.85, 0.5 + severity * 0.35),
        detail: `低头前倾 ${(severity * 100).toFixed(0)}%`,
      }
    }

    return { type: POSTURE_TYPE.NORMAL, confidence: 1.0, detail: '' }
  }

  /**
   * 跷二郎腿检测
   * 原理：跷二郎腿时x轴有明显偏移，y轴出现周期性微振
   * @private
   */
  _detectLegCross(buffer) {
    const avgX = this._calcAxisMean(buffer, 'x')
    const variance = this._calcVariance(buffer)

    // 需要一定活动量（纯静止无法判断）
    if (variance < 0.005 || variance > 0.1) {
      return { type: POSTURE_TYPE.NORMAL, confidence: 1.0, detail: '' }
    }

    const X_OFFSET_THRESHOLD = 0.25
    const hasXOffset = Math.abs(avgX) > X_OFFSET_THRESHOLD
    const hasYOscillation = this._detectPeriodicOscillation(buffer, 'y')

    if (hasXOffset && hasYOscillation) {
      return {
        type: POSTURE_TYPE.LEG_CROSS,
        confidence: 0.65,
        detail: '疑似跷二郎腿',
      }
    }

    return { type: POSTURE_TYPE.NORMAL, confidence: 1.0, detail: '' }
  }

  /**
   * 计算三轴方差
   * @private
   */
  _calcVariance(buffer) {
    const n = buffer.length
    if (n < 2) return 0

    let sum = 0
    for (let i = 0; i < n; i++) {
      const s = buffer[i]
      const magnitude = Math.sqrt(s.x * s.x + s.y * s.y + s.z * s.z)
      sum += magnitude
    }
    const mean = sum / n

    let variance = 0
    for (let i = 0; i < n; i++) {
      const s = buffer[i]
      const magnitude = Math.sqrt(s.x * s.x + s.y * s.y + s.z * s.z)
      variance += (magnitude - mean) * (magnitude - mean)
    }
    return variance / n
  }

  /**
   * 计算指定轴均值
   * @private
   */
  _calcAxisMean(buffer, axis) {
    const n = buffer.length
    if (n === 0) return 0
    let sum = 0
    for (let i = 0; i < n; i++) {
      sum += buffer[i][axis]
    }
    return sum / n
  }

  /**
   * 检测周期性微振（简化版：检测符号变化频率）
   * @private
   */
  _detectPeriodicOscillation(buffer, axis) {
    const n = buffer.length
    if (n < 30) return false

    // 计算符号变化次数
    let signChanges = 0
    for (let i = 1; i < n; i++) {
      if ((buffer[i][axis] >= 0 && buffer[i - 1][axis] < 0) ||
        (buffer[i][axis] < 0 && buffer[i - 1][axis] >= 0)) {
        signChanges++
      }
    }

    // 周期性振荡：符号变化频率在合理范围内
    const changeRate = signChanges / n
    return changeRate > 0.1 && changeRate < 0.5
  }

  /**
   * 获取今日久坐总时长（毫秒）
   */
  getTodaySedentaryMs() {
    let total = this.todaySedentaryMs
    if (this.sitStartTime) {
      total += Date.now() - this.sitStartTime
    }
    return total
  }

  /**
   * 重置今日统计（每日零点调用）
   */
  resetDailyStats() {
    this.todaySedentaryMs = 0
    this.sitStartTime = null
  }

  /**
   * 获取体态类型中文名
   */
  static getPostureName(type) {
    return POSTURE_NAME[type] || '未知'
  }
}

// 导出
export { POSTURE_TYPE, POSTURE_NAME }
export default PostureDetector

/**
 * anonymizer.js - 穿戴隐私数据本地脱敏
 *
 * 对传感器和健康数据进行本地匿名化处理：
 * - 心率：降采样到5分钟粒度，保留区间特征，去除精确时间戳
 * - 步数：聚合为小时粒度
 * - 加速度：仅保留统计特征向量（方差、主轴方向）
 * - 压力：降采样到10分钟粒度
 *
 * 原则：数据可用不可见，只保留体态分析有效特征
 */

// 脱敏数据类型标识
const ANON_TYPE = {
  HR_FEATURE: 'hr_feature',           // 心率特征
  ACCEL_FEATURE: 'accel_feature',     // 加速度特征
  STEP_FEATURE: 'step_feature',       // 步数特征
  STRESS_FEATURE: 'stress_feature',   // 压力特征
  POSTURE_FEATURE: 'posture_feature', // 体态特征
}

// 心率区间分类
const HR_ZONE = {
  REST: { min: 0, max: 60, label: '静息' },
  NORMAL: { min: 60, max: 100, label: '正常' },
  ELEVATED: { min: 100, max: 140, label: '偏高' },
  HIGH: { min: 140, max: 200, label: '过高' },
}

class Anonymizer {
  constructor() {
    // 心率缓冲区（用于5分钟降采样）
    this.hrBuffer = []
    this.hrBufferStartTime = null
    // 压力缓冲区（用于10分钟降采样）
    this.stressBuffer = []
    this.stressBufferStartTime = null
    // 步数缓冲区（用于小时聚合）
    this.stepBuffer = []
    this.stepBufferHour = null
  }

  /**
   * 脱敏心率数据
   * @param {Object} rawData - { timeStamp: number, value: number }
   * @returns {Object|null} 脱敏后的特征，或null（未到降采样时间）
   */
  anonymizeHeartRate(rawData) {
    const now = rawData.timeStamp
    const hourBucket = Math.floor(now / 3600000)

    // 初始化缓冲区
    if (this.hrBufferStartTime === null) {
      this.hrBufferStartTime = now
    }

    // 检查是否在同一个5分钟窗口
    const elapsed = now - this.hrBufferStartTime
    const FIVE_MINUTES = 5 * 60 * 1000

    this.hrBuffer.push(rawData.value)

    if (elapsed < FIVE_MINUTES) {
      return null // 未到降采样时间
    }

    // 生成脱敏特征
    const values = this.hrBuffer
    const feature = {
      type: ANON_TYPE.HR_FEATURE,
      hourBucket: hourBucket,
      avgValue: Math.round(this._calcMean(values)),
      minValue: Math.min(...values),
      maxValue: Math.max(...values),
      zone: this._classifyHRZone(this._calcMean(values)),
      sampleCount: values.length,
      // 不保留精确时间戳
      // 不保留每个精确数值
    }

    // 重置缓冲区
    this.hrBuffer = []
    this.hrBufferStartTime = now

    return feature
  }

  /**
   * 脱敏加速度数据（用于体态分析）
   * @param {Array} samples - [{ x, y, z }] 最近2秒的数据
   * @returns {Object} 脱敏后的特征向量
   */
  anonymizeAcceleration(samples) {
    if (!samples || samples.length === 0) {
      return null
    }

    const n = samples.length

    // 计算各轴均值
    const avgX = this._calcAxisMean(samples, 'x')
    const avgY = this._calcAxisMean(samples, 'y')
    const avgZ = this._calcAxisMean(samples, 'z')

    // 计算各轴方差
    const varX = this._calcAxisVariance(samples, 'x')
    const varY = this._calcAxisVariance(samples, 'y')
    const varZ = this._calcAxisVariance(samples, 'z')

    // 确定主轴方向（重力方向）
    const dominantAxis = this._getDominantAxis(avgX, avgY, avgZ)

    // 计算总方差（用于判断静止/运动）
    const totalVariance = varX + varY + varZ

    return {
      type: ANON_TYPE.ACCEL_FEATURE,
      timestamp: Date.now(),
      avgX: avgX.toFixed(3),
      avgY: avgY.toFixed(3),
      avgZ: avgZ.toFixed(3),
      varX: varX.toFixed(4),
      varY: varY.toFixed(4),
      varZ: varZ.toFixed(4),
      dominantAxis: dominantAxis,
      isStationary: totalVariance < 0.01,
      sampleCount: n,
      // 不保留原始坐标序列
      // 不保留精确采样时间
    }
  }

  /**
   * 脱敏体态检测结果
   * @param {Object} postureResult - 体态检测器输出
   * @returns {Object} 脱敏后的体态记录
   */
  anonymizePostureResult(postureResult) {
    return {
      type: ANON_TYPE.POSTURE_FEATURE,
      timestamp: Date.now(),
      postureType: postureResult.type,
      confidence: postureResult.confidence,
      // 不保留详细检测参数
    }
  }

  /**
   * 脱敏步数数据
   * @param {Object} rawData - { timeStamp: number, value: number }
   * @returns {Object|null} 脱敏后的特征
   */
  anonymizeStep(rawData) {
    const hour = new Date(rawData.timeStamp).getHours()
    const hourBucket = Math.floor(rawData.timeStamp / 3600000)

    if (this.stepBufferHour === null) {
      this.stepBufferHour = hourBucket
    }

    // 检查是否在同一小时
    if (hourBucket !== this.stepBufferHour) {
      // 生成上一小时的脱敏特征
      const feature = {
        type: ANON_TYPE.STEP_FEATURE,
        hourBucket: this.stepBufferHour,
        totalSteps: this.stepBuffer.reduce((a, b) => a + b, 0),
        sampleCount: this.stepBuffer.length,
      }
      // 重置缓冲区
      this.stepBuffer = [rawData.value]
      this.stepBufferHour = hourBucket
      return feature
    }

    this.stepBuffer.push(rawData.value)
    return null
  }

  /**
   * 脱敏压力数据
   * @param {Object} rawData - { timeStamp: number, value: number }
   * @returns {Object|null} 脱敏后的特征
   */
  anonymizeStress(rawData) {
    const now = rawData.timeStamp

    if (this.stressBufferStartTime === null) {
      this.stressBufferStartTime = now
    }

    const elapsed = now - this.stressBufferStartTime
    const TEN_MINUTES = 10 * 60 * 1000

    this.stressBuffer.push(rawData.value)

    if (elapsed < TEN_MINUTES) {
      return null
    }

    const values = this.stressBuffer
    const feature = {
      type: ANON_TYPE.STRESS_FEATURE,
      hourBucket: Math.floor(this.stressBufferStartTime / 3600000),
      avgValue: Math.round(this._calcMean(values)),
      maxValue: Math.max(...values),
      sampleCount: values.length,
    }

    this.stressBuffer = []
    this.stressBufferStartTime = now

    return feature
  }

  /**
   * 心率区间分类
   * @private
   */
  _classifyHRZone(value) {
    for (const [key, zone] of Object.entries(HR_ZONE)) {
      if (value >= zone.min && value < zone.max) {
        return zone.label
      }
    }
    return '未知'
  }

  /**
   * 计算均值
   * @private
   */
  _calcMean(arr) {
    if (arr.length === 0) return 0
    return arr.reduce((a, b) => a + b, 0) / arr.length
  }

  /**
   * 计算指定轴均值
   * @private
   */
  _calcAxisMean(samples, axis) {
    const n = samples.length
    if (n === 0) return 0
    let sum = 0
    for (let i = 0; i < n; i++) {
      sum += samples[i][axis]
    }
    return sum / n
  }

  /**
   * 计算指定轴方差
   * @private
   */
  _calcAxisVariance(samples, axis) {
    const n = samples.length
    if (n < 2) return 0
    const mean = this._calcAxisMean(samples, axis)
    let variance = 0
    for (let i = 0; i < n; i++) {
      const diff = samples[i][axis] - mean
      variance += diff * diff
    }
    return variance / n
  }

  /**
   * 获取主轴方向（重力方向）
   * @private
   */
  _getDominantAxis(avgX, avgY, avgZ) {
    const absX = Math.abs(avgX)
    const absY = Math.abs(avgY)
    const absZ = Math.abs(avgZ)
    if (absX >= absY && absX >= absZ) return 'x'
    if (absY >= absX && absY >= absZ) return 'y'
    return 'z'
  }
}

export { ANON_TYPE, HR_ZONE }
export default Anonymizer

/**
 * crypto-store.js - 轻量化AES分级加密本地存储
 *
 * 三级数据安全策略：
 * - L1-普通：体态统计计数，明文存储
 * - L2-敏感：体态异常记录，AES-ECB加密
 * - L3-隐私：心率/压力原始数据，AES-CBC加密
 *
 * 基于 @system.crypto 和 @system.storage 实现
 */

import crypto from '@system.crypto'
import storage from '@system.storage'

// 加密级别常量
const CRYPTO_LEVEL = {
  L1: 'L1',  // 普通（明文）
  L2: 'L2',  // 敏感（AES-ECB）
  L3: 'L3',  // 隐私（AES-CBC）
}

// 密钥配置（实际应从设备安全存储派生）
const KEYS = {
  L2: 'posture_guard_l2_key_16',  // 16字节AES-128密钥
  L3: 'posture_guard_l3_key_16',  // 16字节AES-128密钥
}

class CryptoStore {
  constructor() {
    // 加密统计
    this.stats = {
      encryptCount: 0,
      decryptCount: 0,
      errorCount: 0,
    }
  }

  /**
   * 存储数据（自动分级加密）
   * @param {string} level - 加密级别 'L1'|'L2'|'L3'
   * @param {string} key - 存储键名
   * @param {*} value - 存储值（对象或原始类型）
   * @param {Function} success - 成功回调
   * @param {Function} fail - 失败回调
   */
  save(level, key, value, success, fail) {
    const plain = JSON.stringify(value)

    if (level === CRYPTO_LEVEL.L1) {
      // L1：明文存储
      storage.set({
        key: key,
        value: plain,
        success: () => {
          console.log(`[CryptoStore] L1 save: ${key}`)
          if (success) success()
        },
        fail: (data, code) => {
          console.error(`[CryptoStore] L1 save fail: ${code}`)
          this.stats.errorCount++
          if (fail) fail(data, code)
        },
      })
      return
    }

    // L2/L3：AES加密后存储
    const encKey = crypto.btoa(KEYS[level])

    crypto.encrypt({
      data: plain,
      key: encKey,
      algo: 'AES',
      success: (res) => {
        this.stats.encryptCount++
        storage.set({
          key: key,
          value: res.data,
          success: () => {
            console.log(`[CryptoStore] ${level} save: ${key}`)
            if (success) success()
          },
          fail: (data, code) => {
            console.error(`[CryptoStore] ${level} storage fail: ${code}`)
            this.stats.errorCount++
            if (fail) fail(data, code)
          },
        })
      },
      fail: (data, code) => {
        console.error(`[CryptoStore] ${level} encrypt fail: ${code}`)
        this.stats.errorCount++
        if (fail) fail(data, code)
      },
    })
  }

  /**
   * 读取数据（自动解密）
   * @param {string} level - 加密级别
   * @param {string} key - 存储键名
   * @param {Function} callback - 回调 (value) => {}
   * @param {Function} fail - 失败回调
   */
  load(level, key, callback, fail) {
    storage.get({
      key: key,
      success: (encrypted) => {
        if (level === CRYPTO_LEVEL.L1) {
          // L1：明文直接解析
          try {
            callback(JSON.parse(encrypted))
          } catch (e) {
            callback(encrypted)
          }
          return
        }

        // L2/L3：AES解密
        const encKey = crypto.btoa(KEYS[level])

        crypto.decrypt({
          data: encrypted,
          key: encKey,
          algo: 'AES',
          success: (res) => {
            this.stats.decryptCount++
            try {
              callback(JSON.parse(res.data))
            } catch (e) {
              callback(res.data)
            }
          },
          fail: (data, code) => {
            console.error(`[CryptoStore] ${level} decrypt fail: ${code}`)
            this.stats.errorCount++
            if (fail) fail(data, code)
          },
        })
      },
      fail: (data, code) => {
        console.error(`[CryptoStore] ${level} load fail: ${code}`)
        this.stats.errorCount++
        if (fail) fail(data, code)
      },
    })
  }

  /**
   * 删除数据
   * @param {string} key - 存储键名
   * @param {Function} success - 成功回调
   */
  remove(key, success) {
    storage.delete({
      key: key,
      success: () => {
        console.log(`[CryptoStore] delete: ${key}`)
        if (success) success()
      },
      fail: (data, code) => {
        console.error(`[CryptoStore] delete fail: ${code}`)
        this.stats.errorCount++
      },
    })
  }

  /**
   * 批量删除（按前缀匹配）
   * 注意：storage API 不支持遍历，需要外部维护键名列表
   * @param {Array} keys - 键名数组
   * @param {Function} callback - 完成回调
   */
  batchRemove(keys, callback) {
    let remaining = keys.length
    if (remaining === 0) {
      if (callback) callback()
      return
    }

    keys.forEach((key) => {
      storage.delete({
        key: key,
        success: () => {
          remaining--
          if (remaining === 0 && callback) callback()
        },
        fail: () => {
          remaining--
          if (remaining === 0 && callback) callback()
        },
      })
    })
  }

  /**
   * 清空所有数据
   * @param {Function} success - 成功回调
   */
  clearAll(success) {
    storage.clear({
      success: () => {
        console.log('[CryptoStore] clearAll')
        this.stats = { encryptCount: 0, decryptCount: 0, errorCount: 0 }
        if (success) success()
      },
      fail: (data, code) => {
        console.error(`[CryptoStore] clearAll fail: ${code}`)
      },
    })
  }

  /**
   * 获取加密统计信息
   */
  getStats() {
    return { ...this.stats }
  }
}

export { CRYPTO_LEVEL }
export default CryptoStore

/**
 * data-manager.js - 数据生命周期管理
 *
 * 管理所有本地数据的存储、查询、过期清理：
 * - 体态统计数据（L1）
 * - 体态异常记录（L2加密）
 * - 心率/压力原始数据（L3加密）
 * - 数据过期自动销毁
 * - 一键清除隐私数据
 */

import CryptoStore, { CRYPTO_LEVEL } from './crypto-store'

// 数据类型常量
const DATA_TYPE = {
  POSTURE_DAILY: 'posture_daily',         // 每日体态统计
  POSTURE_ALERT: 'posture_alert',         // 体态异常记录
  HR_FEATURE: 'hr_feature',               // 心率脱敏特征
  STRESS_FEATURE: 'stress_feature',       // 压力脱敏特征
  SETTINGS: 'settings',                   // 应用设置
}

// 数据过期时间配置（毫秒）
const EXPIRY = {
  [DATA_TYPE.POSTURE_DAILY]: 7 * 24 * 3600 * 1000,    // 7天
  [DATA_TYPE.POSTURE_ALERT]: 30 * 24 * 3600 * 1000,   // 30天
  [DATA_TYPE.HR_FEATURE]: 30 * 24 * 3600 * 1000,      // 30天
  [DATA_TYPE.STRESS_FEATURE]: 30 * 24 * 3600 * 1000,  // 30天
}

// 数据加密级别映射
const LEVEL_MAP = {
  [DATA_TYPE.POSTURE_DAILY]: CRYPTO_LEVEL.L1,
  [DATA_TYPE.POSTURE_ALERT]: CRYPTO_LEVEL.L2,
  [DATA_TYPE.HR_FEATURE]: CRYPTO_LEVEL.L3,
  [DATA_TYPE.STRESS_FEATURE]: CRYPTO_LEVEL.L3,
  [DATA_TYPE.SETTINGS]: CRYPTO_LEVEL.L1,
}

class DataManager {
  constructor() {
    this.cryptoStore = new CryptoStore()
    // 键名注册表（用于遍历清理）
    this.keyRegistry = []
  }

  /**
   * 生成存储键名
   * @private
   */
  _makeKey(type, date) {
    const dateStr = date || this._getDateStr()
    return `pg_${type}_${dateStr}`
  }

  /**
   * 获取日期字符串 YYYY-MM-DD
   * @private
   */
  _getDateStr(ts) {
    const d = ts ? new Date(ts) : new Date()
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
  }

  /**
   * 保存体态统计数据
   * @param {Object} stats - { sedentaryCount, headTiltCount, legCrossCount, totalAlerts }
   * @param {Function} callback - 完成回调
   */
  savePostureStats(stats, callback) {
    const key = this._makeKey(DATA_TYPE.POSTURE_DAILY)
    const data = {
      ...stats,
      date: this._getDateStr(),
      timestamp: Date.now(),
    }

    this._registerKey(key)
    this.cryptoStore.save(
      LEVEL_MAP[DATA_TYPE.POSTURE_DAILY],
      key,
      data,
      () => {
        console.log(`[DataManager] save posture stats: ${key}`)
        if (callback) callback(true)
      },
      () => {
        if (callback) callback(false)
      }
    )
  }

  /**
   * 保存体态异常记录
   * @param {Object} alert - { type, confidence, detail, timestamp }
   * @param {Function} callback - 完成回调
   */
  savePostureAlert(alert, callback) {
    const today = this._getDateStr()
    const key = this._makeKey(DATA_TYPE.POSTURE_ALERT) + '_' + Date.now()

    const data = {
      ...alert,
      date: today,
      timestamp: alert.timestamp || Date.now(),
    }

    this._registerKey(key)
    this.cryptoStore.save(
      LEVEL_MAP[DATA_TYPE.POSTURE_ALERT],
      key,
      data,
      () => {
        console.log(`[DataManager] save posture alert`)
        if (callback) callback(true)
      },
      () => {
        if (callback) callback(false)
      }
    )
  }

  /**
   * 保存心率脱敏特征
   * @param {Object} feature - anonymizer 输出的特征
   * @param {Function} callback - 完成回调
   */
  saveHRFeature(feature, callback) {
    const key = this._makeKey(DATA_TYPE.HR_FEATURE) + '_' + feature.hourBucket

    this._registerKey(key)
    this.cryptoStore.save(
      LEVEL_MAP[DATA_TYPE.HR_FEATURE],
      key,
      feature,
      () => {
        console.log(`[DataManager] save HR feature`)
        if (callback) callback(true)
      },
      () => {
        if (callback) callback(false)
      }
    )
  }

  /**
   * 保存压力脱敏特征
   * @param {Object} feature - anonymizer 输出的特征
   * @param {Function} callback - 完成回调
   */
  saveStressFeature(feature, callback) {
    const key = this._makeKey(DATA_TYPE.STRESS_FEATURE) + '_' + feature.hourBucket

    this._registerKey(key)
    this.cryptoStore.save(
      LEVEL_MAP[DATA_TYPE.STRESS_FEATURE],
      key,
      feature,
      () => {
        console.log(`[DataManager] save stress feature`)
        if (callback) callback(true)
      },
      () => {
        if (callback) callback(false)
      }
    )
  }

  /**
   * 加载今日体态统计
   * @param {Function} callback - (data) => {}
   */
  loadTodayPostureStats(callback) {
    const key = this._makeKey(DATA_TYPE.POSTURE_DAILY)
    this.cryptoStore.load(LEVEL_MAP[DATA_TYPE.POSTURE_DAILY], key, callback, () => {
      callback(null)
    })
  }

  /**
   * 加载今日体态异常记录
   * @param {Function} callback - (alerts[]) => {}
   */
  loadTodayAlerts(callback) {
    // 从注册表中筛选今日的异常记录键
    const todayPrefix = this._makeKey(DATA_TYPE.POSTURE_ALERT)
    const todayKeys = this.keyRegistry.filter((k) => k.startsWith(todayPrefix))

    if (todayKeys.length === 0) {
      callback([])
      return
    }

    const alerts = []
    let remaining = todayKeys.length

    todayKeys.forEach((key) => {
      this.cryptoStore.load(LEVEL_MAP[DATA_TYPE.POSTURE_ALERT], key, (data) => {
        if (data) alerts.push(data)
        remaining--
        if (remaining === 0) {
          // 按时间排序
          alerts.sort((a, b) => a.timestamp - b.timestamp)
          callback(alerts)
        }
      }, () => {
        remaining--
        if (remaining === 0) callback(alerts)
      })
    })
  }

  /**
   * 加载指定日期范围的心率特征
   * @param {number} days - 回溯天数
   * @param {Function} callback - (features[]) => {}
   */
  loadHRFeatures(days, callback) {
    const features = []
    let remaining = 0

    for (let i = 0; i < days; i++) {
      const date = new Date()
      date.setDate(date.getDate() - i)
      const dateStr = this._getDateStr(date.getTime())
      const prefix = `pg_${DATA_TYPE.HR_FEATURE}_${dateStr}`
      const keys = this.keyRegistry.filter((k) => k.startsWith(prefix))
      remaining += keys.length

      keys.forEach((key) => {
        this.cryptoStore.load(LEVEL_MAP[DATA_TYPE.HR_FEATURE], key, (data) => {
          if (data) features.push(data)
          remaining--
          if (remaining === 0) callback(features)
        }, () => {
          remaining--
          if (remaining === 0) callback(features)
        })
      })
    }

    if (remaining === 0) callback(features)
  }

  /**
   * 保存应用设置
   * @param {Object} settings
   * @param {Function} callback
   */
  saveSettings(settings, callback) {
    const key = 'pg_settings'
    this._registerKey(key)
    this.cryptoStore.save(CRYPTO_LEVEL.L1, key, settings, () => {
      if (callback) callback(true)
    }, () => {
      if (callback) callback(false)
    })
  }

  /**
   * 加载应用设置
   * @param {Function} callback - (settings) => {}
   */
  loadSettings(callback) {
    this.cryptoStore.load(CRYPTO_LEVEL.L1, 'pg_settings', callback, () => {
      callback({
        sedentaryThreshold: 30 * 60 * 1000, // 默认30分钟
        vibrationEnabled: true,
        alertEnabled: true,
      })
    })
  }

  /**
   * 清理过期数据
   * @param {Function} callback - (cleanedCount) => {}
   */
  cleanExpired(callback) {
    const now = Date.now()
    const expiredKeys = []

    this.keyRegistry.forEach((key) => {
      // 从键名中提取类型
      for (const [type, expiryMs] of Object.entries(EXPIRY)) {
        if (key.includes(type)) {
          // 尝试从键名中提取时间戳或日期
          const dateMatch = key.match(/(\d{4}-\d{2}-\d{2})/)
          if (dateMatch) {
            const dataDate = new Date(dateMatch[1]).getTime()
            if (now - dataDate > expiryMs) {
              expiredKeys.push(key)
            }
          }
          break
        }
      }
    })

    if (expiredKeys.length === 0) {
      if (callback) callback(0)
      return
    }

    // 从注册表中移除过期键
    this.keyRegistry = this.keyRegistry.filter((k) => !expiredKeys.includes(k))

    // 删除过期数据
    this.cryptoStore.batchRemove(expiredKeys, () => {
      console.log(`[DataManager] cleaned ${expiredKeys.length} expired keys`)
      if (callback) callback(expiredKeys.length)
    })
  }

  /**
   * 一键清除所有隐私数据（保留设置）
   * @param {Function} callback - 完成回调
   */
  clearAllPrivacyData(callback) {
    const privacyKeys = this.keyRegistry.filter(
      (k) => !k.includes(DATA_TYPE.SETTINGS)
    )
    this.keyRegistry = this.keyRegistry.filter((k) => k.includes(DATA_TYPE.SETTINGS))

    this.cryptoStore.batchRemove(privacyKeys, () => {
      console.log(`[DataManager] cleared ${privacyKeys.length} privacy keys`)
      if (callback) callback()
    })
  }

  /**
   * 获取数据统计摘要
   * @param {Function} callback - (summary) => {}
   */
  getSummary(callback) {
    const summary = {
      totalKeys: this.keyRegistry.length,
      postureDaily: 0,
      postureAlerts: 0,
      hrFeatures: 0,
      stressFeatures: 0,
    }

    this.keyRegistry.forEach((key) => {
      if (key.includes(DATA_TYPE.POSTURE_DAILY)) summary.postureDaily++
      else if (key.includes(DATA_TYPE.POSTURE_ALERT)) summary.postureAlerts++
      else if (key.includes(DATA_TYPE.HR_FEATURE)) summary.hrFeatures++
      else if (key.includes(DATA_TYPE.STRESS_FEATURE)) summary.stressFeatures++
    })

    summary.cryptoStats = this.cryptoStore.getStats()
    callback(summary)
  }

  /**
   * 注册键名到注册表
   * @private
   */
  _registerKey(key) {
    if (!this.keyRegistry.includes(key)) {
      this.keyRegistry.push(key)
    }
  }
}

export { DATA_TYPE, EXPIRY }
export default DataManager
